// @ts-ignore Generated by the OpenNext build before Wrangler bundles this entry.
import handler from "./.open-next/worker.js";
import * as Sentry from "@sentry/cloudflare";

import { scrubSentryEvent } from "./src/lib/sentry-privacy";

type WorkerEnvironment = Record<string, unknown> & {
  CRON_SECRET?: string;
  SENTRY_DSN?: string;
  WORKER_SELF_REFERENCE?: {
    fetch(request: Request): Promise<Response>;
  };
};

// Cloudflare worker globals come from wrangler-generated types that are
// gitignored. Keep a local stand-in so Next.js typecheck does not depend on
// `pnpm cf-typegen` having run in CI.
type ExecutionContext = {
  waitUntil(promise: Promise<unknown>): void;
};

type ScheduledController = {
  readonly scheduledTime: number;
  readonly cron: string;
};

type ExportedHandler<Env = unknown> = {
  fetch?(
    request: Request,
    env: Env,
    ctx: ExecutionContext,
  ): Response | Promise<Response>;
  scheduled?(
    controller: ScheduledController,
    env: Env,
    ctx: ExecutionContext,
  ): void | Promise<void>;
};

const worker: ExportedHandler<WorkerEnvironment> = {
  fetch(
    request: Request,
    env: WorkerEnvironment,
    ctx: ExecutionContext,
  ) {
    const url = new URL(request.url);
    const requiresHttps = url.protocol === "http:";
    const requiresCanonicalHost = url.hostname === "www.themys.ca";

    if (requiresHttps || requiresCanonicalHost) {
      url.protocol = "https:";
      if (requiresCanonicalHost) url.hostname = "themys.ca";
      return Response.redirect(url, 308);
    }

    return handler.fetch(request, env, ctx);
  },

  async scheduled(
    _event: ScheduledController,
    env: WorkerEnvironment,
    ctx: ExecutionContext,
  ) {
    if (!env.CRON_SECRET) throw new Error("CRON_SECRET is not configured");
    if (!env.WORKER_SELF_REFERENCE) {
      throw new Error("WORKER_SELF_REFERENCE is not configured");
    }

    // Send cron work through the Worker itself so OpenNext establishes the
    // same request-scoped Cloudflare context used by route handlers. Calling
    // server code directly here skips that setup on a cold scheduled event.
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE
        .fetch(new Request("https://themys.ca/api/monitor/check", {
          method: "POST",
          // Keep the cron credential out of Authorization. Clerk middleware
          // treats bearer values as session JWTs before the route can verify
          // CRON_SECRET, which causes valid cron requests to be rejected.
          headers: { "x-cron-secret": env.CRON_SECRET },
        }))
        .then((response) => {
          if (!response.ok) {
            throw new Error(`Scheduled monitoring request failed with ${response.status}`);
          }
        }),
    );
  },
};

export default Sentry.withSentry<WorkerEnvironment>(
  (env: WorkerEnvironment) => env.SENTRY_DSN
    ? {
        dsn: env.SENTRY_DSN,
        sendDefaultPii: false,
        beforeSend: scrubSentryEvent,
        tracesSampleRate: 0.1,
        // Keep workerd on the SDK's error-reporting path. Installing its
        // compatibility OpenTelemetry provider has caused recursive tracing in
        // this OpenNext runtime and is not required for exception delivery.
        skipOpenTelemetrySetup: true,
      }
    : undefined,
  worker,
);
